 const p=G.colonists[i], d=$('#founderEdit');$('#founderFace').innerHTML=polyPortrait(i);$('#founderName').value=p.name;
 $('#axisFields').replaceChildren();$('#foundSkills').textContent=Object.entries(p.skills).map(([k,v])=>k+' '+v).join('　·　');
