function state(){return G.workshop??={points:6,turn:0,studied:[],laws:[],stock:{},last:G.tick}}
function lineStep(){
 const s=state(),nodes=G.buildings.filter(b=>machines[b.id]);s.turn++;if(s.turn%5===0)s.points++;
 const at=new Map(nodes.map(b=>[b.x+','+b.y,b]));
 for(const b of nodes){b.bin??={};b.status='待料';const [,input,cost,out,base]=machines[b.id];const capacity=8;
 const amount=base+(b.id==='pit'&&s.laws.includes('加速开采')?1:0);
 if(out){if((b.bin[out]||0)+amount>capacity)b.status='输出积压';else if(!cost||(b.bin[input]||0)>=cost){if(cost)b.bin[input]-=cost;b.bin[out]=(b.bin[out]||0)+amount;b.status='本轮生产 '+out+' ×'+amount}}
 }
 const arrivals=[];
 for(const b of nodes){if(b.id==='store')continue;const [, , ,out]=machines[b.id];const keys=b.id==='belt'?Object.keys(b.bin):[out];
 const dest=at.get((b.x+1)+','+b.y);if(!dest){b.status+=' · 东侧未接通';continue}
 let budget=1+(b.id==='belt'?Number(s.studied.includes('并行转运'))+Number(s.laws.includes('集中转运')):0);
 for(const k of keys){if(!b.bin[k]||!budget)continue;if(!['belt','store'].includes(dest.id)&&machines[dest.id][1]!==k){b.status='下游不接收'+k;continue}
 const n=Math.min(b.bin[k],budget,dest.id==='store'?Infinity:8-(dest.bin[k]||0));if(!n){b.status='下游已满';continue}b.bin[k]-=n;budget-=n;arrivals.push([dest,k,n]);if(b.id==='belt')b.status='转运 '+k}
 }
 for(const [d,k,n] of arrivals){const bin=d.id==='store'?s.stock:d.bin;bin[k]=(bin[k]||0)+n;if(d.id==='store')d.status='已入库 '+k}
}
