function renderRoster(){$('#roster').innerHTML=G.colonists.slice(0,G.count).map((p,i)=>`<button type="button" data-founder="${i}" class="pawn-card"><span class="miniFace">${polyPortrait(i)}</span><b>${p.name}</b><small>${p.traits.join(' / ')}</small><small>价值：${p.values.join('、')}</small><small>强项：${Object.entries(p.skills).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>x[0]+' '+x[1]).join('、')}</small><small>编辑人物 ›</small></button>`).join('');$$('[data-founder]').forEach(b=>b.onclick=()=>editFounder(+b.dataset.founder))}
