function hash(x,y,k=0){let n=x*374761393+y*668265263+G.seed+k*144269;n=(n^(n>>13))*1274126177;return((n^(n>>16))>>>0)/4294967295}const goods=['ITM-WOOD','ITM-STEEL','ITM-SILVER','ITM-FOOD','ITM-STONE','ITM-PART','ITM-MED'];
