const cap=(v,min,max)=>Math.max(min,Math.min(max,v));
function noise(x,y,size,k){const a=Math.floor(x/size),b=Math.floor(y/size);let u=x/size-a,v=y/size-b;u=u*u*(3-2*u);v=v*v*(3-2*v);const mix=(a,b,t)=>a+(b-a)*t;return mix(mix(hash(a,b,k),hash(a+1,b,k),u),mix(hash(a,b+1,k),hash(a+1,b+1,k),u),v)}
function worldField(x,y){const phase=(G.seed%719)/180,river=4.2+1.15*Math.sin(x*.54+phase)+.4*Math.sin(x*1.34+phase),ridge=Math.abs(y-(1.7+.23*x+.94*Math.sin(x*.73+phase)));const lake=((x-9.1)/1.05)**2+((y-(4.2+1.15*Math.sin(9.1*.54+phase)+.4*Math.sin(9.1*1.34+phase)))/.66)**2;return {river:y-river,ridge,lake}}
const worldPos=(q,r)=>[q+(r%2)*.5,r];
function tileType(q,r){const f=worldField(...worldPos(q,r));return f.lake<.75?'湖泊':Math.abs(f.river)<.55?'河谷':f.ridge<.65?'山地':r<2?'寒原':r>6?'疏林':'平原'}
function terrainData(x,y){if(MAP_W===72)return compactTile(x,y);
 const land=G.landing||[5,4],key=[G.seed,...land].join();if(key!==cacheKey){cache.clear();cacheKey=key}
 const id=x+','+y;if(cache.has(id))return cache.get(id);
 const [cx,cy]=worldPos(...land),X=cx+(x-150)/300,Y=cy+(y-150)/300,f=worldField(X,Y),wx=Math.round(X*300),wy=Math.round(Y*300);
 const broad=noise(wx,wy,45,19),detail=noise(wx,wy,12,23);
 const valley=wy+42*Math.sin(wx/84)+24*Math.sin(wx/33)+55*(noise(wx,wy,130,71)-.5);
 const band=Math.round(valley/185),bed=valley-band*185,wet=Math.abs(bed);
 const basin=noise(wx,band*185,80,73),width=1.8+2.8*broad+Math.max(0,basin-.6)*85;
 const water=Math.abs(f.river)<.018+.012*broad||f.lake<.9+.12*broad||wet<width; const vein=Math.abs(noise(wx,wy,56,47)-.54)<.045+.02*detail&&broad>.49;
 const hill=f.ridge<.36||broad>.66;
 const name=water?'浅水':vein?'铁矿脉':hill?'裸岩':'草地';
 const color=water?(detail>.5?'#477c88':'#528693'):vein?'#866b59':hill?(detail>.5?'#8b8978':'#787c71'):['#677f63','#748964','#83936a'][Math.min(2,Math.floor(broad*3))];
 const cell={name,color,fert:water?0:hill?15:Math.round(65+45*broad),bearing:water?'无':hill?'高':'普通'};cache.set(id,cell);return cell
}
