 const pal={'山地':'#929183','湖泊':'#498595','河谷':'#6e9b86','平原':'#94a36e','疏林':'#6d8c65','寒原':'#a2afa0'};
 let cells='';for(let r=0;r<9;r++)for(let q=0;q<14;q++){const x=12+(q+r%2*.5)*17.32,y=12+15*r,kind=tileType(q,r),h=hash(q,r,14),points=[[0,-10],[8.66,-5],[8.66,5],[0,10],[-8.66,5],[-8.66,-5]].map(([a,b])=>[x+a,y+b].join(',')).join(' ');const selected=select[0]===q&&select[1]===r;cells+='<g data-cell="'+q+','+r+'" tabindex="0" role="button" aria-label="'+kind+' '+q+','+r+'"><title>'+kind+' ('+q+','+r+')</title><polygon points="'+points+'" fill="'+pal[kind]+'" stroke="'+(selected?'#fff1a5':'#344338')+'" stroke-width="'+(selected?2.3:.35)+'"/><path d="M'+x+' '+(y-9)+'l8 5 -6 8z" fill="#19322b" opacity="'+(.08+h*.18)+'"/>'+(kind==='山地'?'<path d="M'+(x-6)+' '+(y+4)+'l5 -11 7 11z" fill="#646861"/><path d="M'+(x-1)+' '+(y-7)+'l3 6 -4 -2z" fill="#dfdcca"/>':'')+(towns.some(t=>t[0]===q&&t[1]===r)?'<circle cx="'+x+'" cy="'+y+'" r="3" fill="#ae503a" stroke="white"/>':'')+(home&&q===home[0]&&r===home[1]?'<circle cx="'+x+'" cy="'+y+'" r="3.7" fill="#ffe892" stroke="#393a31"/>':'')+'</g>'}
