function route(a,b){const queue=[[a]],seen=new Set([a.join()]);for(const path of queue){const [q,r]=path.at(-1);if(q===b[0]&&r===b[1])return path;const k=r%2;for(const n of [[q-1,r],[q+1,r],[q+k-1,r-1],[q+k,r-1],[q+k-1,r+1],[q+k,r+1]]){if(n[0]<0||n[0]>13||n[1]<0||n[1]>8||seen.has(n.join())||tileType(...n)==='湖泊')continue;seen.add(n.join());queue.push([...path,n])}}return []}
