function mapPeople(){(G.people||[]).forEach((p,i)=>{if(G.trip?.ids.includes(p.id))return;const step=p.motion?.step,f=step?cap((G.tick-step.start)/96,0,1):0,px=step?step.from.x+(step.to.x-step.from.x)*f:p.position.x,py=step?step.from.y+(step.to.y-step.from.y)*f:p.position.y,x=(px+.5)*TILE,y=(py+.5)*TILE;ctx.save();if(i===memberIndex){ctx.strokeStyle='#e7d69d';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,4.5,0,Math.PI*2);ctx.stroke()}ctx.fillStyle=p.motion?'#e2cba4':'#d9dfc9';ctx.beginPath();ctx.arc(x,y,2.6,0,Math.PI*2);ctx.fill();if(p.motion?.kind==='order'&&!p.motion.path.length&&!step){ctx.fillStyle='#e3cc94';ctx.fillRect(px*TILE+TILE*.3,py*TILE+TILE*.75,TILE*.4*cap(p.job.progress/100,0,1),1.5)}ctx.restore()})}
function medical(p){const b=p.body;if(!b.parts){b.parts=Object.fromEntries(['头部','左臂','右臂','左腿','右腿','心脏','左肺','右肺','肝脏','胃','左肾','右肾'].map(k=>[k,100]));b.chronic=p.conditions||[]}return [['生命',b.health+' / 100'],['疼痛',b.pain],['行动能力',b.mobility+'%'],...Object.entries(b.parts).map(([k,v])=>[k,v===100?'完好':v+' / 100']),['慢性病',b.chronic.length?b.chronic.join('、'):'无已知慢性病']]}
function compactTile(x,y){
 const key=x+','+y;if(cache.has(key))return cache.get(key);
 const phase=(G.seed%197)/40,land=G.landing||[5,4],ridge=noise(x+land[0]*18,y+land[1]*9,13,17),grain=noise(x,y,5,8);
 const bend=13+4*Math.sin(y*.12+phase)+3*Math.sin(y*.058+phase),shore=((x-12)/8)**2+((y-19)/6)**2;
 const ford=Math.abs(y-34)<=1;const water=!ford&&(Math.abs(x-bend)<1.15+.75*grain||shore<.87+.25*grain);
 const name=water?'浅水':Math.abs(x-bend)<2?'河滩':ridge>.69?'岩地':'草地',color=water?(grain>.5?'#568795':'#65969e'):name==='河滩'?'#a89f7a':name==='岩地'?(grain>.5?'#898979':'#959282'):['#819265','#88996c','#91a172'][Math.min(2,Math.floor(grain*3))];
 const obj={name,color,fert:water?0:name==='岩地'?25:Math.round(65+28*ridge),bearing:water?'无':'普通'};cache.set(key,obj);return obj
}
function configureRegion(restore=false){G.stockCells??={};
 MAP_W=MAP_H=restore?(G.regionSize||300):72;G.regionSize=MAP_W;cache.clear();cacheKey='';heads.clear();
 if(!restore){G.camera={x:36.5*TILE,y:36.5*TILE,zoom:1.18};G.selected={x:36,y:36}}
 if(G.fieldObjects)return;
 distributeTerrain()
}
const itemNames={'ITM-CRYSTAL':'晶矿','ITM-WOOD':'木材','ITM-STONE':'石料','ITM-IRON-ORE':'铁矿石','ITM-COPPER-ORE':'铜矿石','ITM-COAL':'煤','ITM-FOOD':'食物','ITM-MED':'药草'};
function paintObject(o){if(!o)return;ctx.save();ctx.translate(o.x*TILE,o.y*TILE);ctx.translate(TILE*.1,TILE*.1);ctx.scale(TILE*.8/24,TILE*.8/24);
 const poly=(fill,pts)=>{ctx.fillStyle=fill;ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()};
 if(o.kind==='grass'){ctx.strokeStyle='#68805b';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(7,16);ctx.lineTo(6,13);ctx.moveTo(10,17);ctx.lineTo(12,12);ctx.moveTo(14,17);ctx.lineTo(16,14);ctx.stroke()}else if(o.kind==='crystal'){poly('#577d86',[[5,19],[6,10],[10,6],[13,15],[17,5],[20,8],[17,20]]);poly('#a6d1c6',[[13,16],[17,5],[16,15],[14,19]])}else if(o.kind==='tree'){ctx.fillStyle='#68503d';ctx.fillRect(10,14,4,8);poly('#365f4c',[[2,16],[7,8],[11,2],[17,5],[22,16],[15,19],[7,19]]);poly('#72905b',[[3,15],[11,2],[13,11],[8,16]]);poly('#507550',[[11,2],[17,5],[20,12],[13,11]])}
 else if(o.kind==='pile'){poly('#c5a578',[[3,12],[12,7],[21,11],[13,17]]);poly('#876644',[[3,12],[13,17],[13,22],[3,17]]);poly('#a58055',[[13,17],[21,11],[21,17],[13,22]])}
 else if(['berries','herb'].includes(o.kind)){poly('#476744',[[3,18],[6,9],[11,14],[15,5],[16,14],[21,10],[19,20]]);for(const [x,y] of [[7,13],[13,14],[17,10]]){ctx.fillStyle=o.kind==='herb'?'#eee6ab':'#cc6d69';ctx.beginPath();ctx.arc(x,y,2,0,7);ctx.fill()}}
 else{const pigment={stone:'#8d9583',iron:'#9a8874',copper:'#ae8d6b',coal:'#555a65'}[o.kind];poly('#646960',[[2,19],[6,10],[11,6],[18,8],[22,17],[18,21],[7,21]]);poly(pigment,[[4,17],[7,10],[12,7],[17,9],[12,15]]);poly('#767c74',[[12,15],[17,9],[20,17],[17,19]]);if(o.kind!=='stone'){ctx.strokeStyle={copper:'#ffbd83',iron:'#e7b496',coal:'#2f3441'}[o.kind];ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(6,16);ctx.lineTo(10,12);ctx.lineTo(14,13);ctx.stroke()}}
 ctx.restore()}
function targets(cmd,b){if(cmd==='拆除')return G.buildings.filter(o=>o.x<b.x+b.w&&o.x+o.w>b.x&&o.y<b.y+b.h&&o.y+o.h>b.y);
 const hits=[];for(let y=b.y;y<b.y+b.h;y++)for(let x=b.x;x<b.x+b.w;x++){const o=G.fieldObjects?.[x+','+y];if(o&&(o.kind==='pile'?'搬运':resources[o.kind].cmd)===cmd)hits.push(o)}return hits}
function distributeTerrain(){
 const buckets=Array.from({length:36},()=>[]),mid=Math.floor(MAP_W/2),occ=new Set();
 for(const b of G.buildings)for(let y=b.y;y<b.y+b.h;y++)for(let x=b.x;x<b.x+b.w;x++)occ.add(x+','+y);
 let seed=G.seed>>>0;const roll=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);
 function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(roll()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
 for(let y=0;y<MAP_H;y++)for(let x=0;x<MAP_W;x++){if(terrainData(x,y).name==='浅水'||occ.has(x+','+y)||(x>=mid-2&&x<=mid+9&&y>=mid-2&&y<=mid+5))continue;buckets[Math.floor(y*6/MAP_H)*6+Math.floor(x*6/MAP_W)].push({x,y})}
 buckets.forEach(shuffle);shuffle(buckets);const total=Math.round(MAP_W*MAP_H*.33),tree=.15+roll()*.10,rare=.03+roll()*.03;const fractions=[['tree',tree],['berries',.02],['herb',.02],['stone',.2],['iron',.1],['copper',rare/2],['crystal',rare/2],['grass',0]];G.fieldObjects={};let placed=0,cursor=0;
 for(const [kind,ratio] of fractions){const count=ratio?Math.round(total*ratio):total-placed;for(let i=0;i<count;i++){let tries=0;while(!buckets[cursor%36].length&&tries++<36)cursor++;const p=buckets[cursor++%36].pop();if(!p)return;G.fieldObjects[p.x+','+p.y]={...p,kind};placed++}}
}
const taskTime={'砍伐':96,'采矿':144,'搬运':54,'采集':72,'拆除':108};
const inside=(p,z)=>p.x>=z.x&&p.x<z.x+z.w&&p.y>=z.y&&p.y<z.y+z.h;
function homes(){return G.zones.filter(z=>z.type==='居住区')}
function allowed(p,cell){return !p.stayHome||!homes().length||homes().some(z=>inside(cell,z))}
function walkable(c){return c.x>=0&&c.y>=0&&c.x<MAP_W&&c.y<MAP_H&&terrainData(c.x,c.y).name!=='浅水'&&!G.buildings.some(b=>inside(c,b))}
function paths(p,goals,returning=false){
 const pos=p.position,start=pos.y*MAP_W+pos.x,seen=new Map([[start,-1]]),queue=[start];for(let i=0;i<queue.length;i++){const v=queue[i],x=v%MAP_W,y=Math.floor(v/MAP_W),found=goals.get(v);if(found){const path=[];for(let k=v;seen.get(k)!==-1;k=seen.get(k))path.push({x:k%MAP_W,y:Math.floor(k/MAP_W)});return {found,path:path.reverse()}}
 for(const [dx,dy] of [[1,0],[0,1],[-1,0],[0,-1]]){const c={x:x+dx,y:y+dy},k=c.y*MAP_W+c.x;if(!seen.has(k)&&walkable(c)&&(returning||allowed(p,c))){seen.set(k,v);queue.push(k)}}}return null
}
function executeArea(cmd,b){const tasks=G.orders??=[],known=new Set(tasks.map(t=>t.cmd+':'+t.x+','+t.y));let count=0;
 for(const o of targets(cmd,b)){const key=cmd+':'+o.x+','+o.y;if(known.has(key))continue;tasks.push({cmd,x:o.x,y:o.y,w:o.w||1,h:o.h||1,kind:o.kind||o.id,work:0});known.add(key);count++}
 const msg=cmd+' · 新增 '+count+' 项，等待 '+tasks.filter(t=>!t.owner).length+' 项';notify(msg);$('#tileReadout').textContent=msg
}
function releasePawn(p){const t=G.orders?.find(t=>t.owner===p.id);if(t)delete t.owner;delete p.motion;p.job={name:'待命',progress:0,target:'聚落',reason:'等待工作'}}
function assign(p,route,kind,label){p.motion={kind,path:route.path,label};p.job={name:label,progress:0,target:'聚落地块',reason:kind==='order'?'玩家指令':label}}
function confirmMove(p,c){if(!walkable(c)||!allowed(p,c))return notify('该地块不可通行或在允许范围外');const r=paths(p,new Map([[c.y*MAP_W+c.x,true]]));if(!r)return notify('没有可通行路径');releasePawn(p);assign(p,r,'manual','前往指定地点');notify(p.name+' → '+c.x+', '+c.y)}
function completeOrder(t,p){
 const k=t.x+','+t.y,o=G.fieldObjects[k];if(t.cmd==='拆除'){G.buildings=G.buildings.filter(b=>!(b.x===t.x&&b.y===t.y&&b.id===t.kind))}
 else if(o&&t.kind===o.kind){const r=o.kind==='pile'?o:resources[o.kind];if(t.cmd==='搬运'){G.inventory[r.item]=(G.inventory[r.item]||0)+r.amount;delete G.fieldObjects[k]}else G.fieldObjects[k]={x:t.x,y:t.y,kind:'pile',item:r.item,amount:r.amount,source:p.name+' · '+t.cmd+' '+k}}
 const text=p.name+'完成'+t.cmd+'（'+t.x+', '+t.y+'）';p.memories.unshift({factId:'WORK-'+G.tick+'-'+p.id,appraisal:text,intensity:2});p.memories.splice(24);G.orders.splice(G.orders.indexOf(t),1);releasePawn(p);refreshHUD()
}
const stockDefs=new Map(DB.items.map(i=>[i.物品ID,{name:i.名称,limit:Number(i.堆叠上限)||50}]));
for(const [id,name,limit] of [['ITM-FOOD','食物',40],['ITM-MED','药草',25],['ITM-CRYSTAL','晶矿',50],['ITM-PART','零件',50],['ITM-SILVER','银币',250],['ITM-STEEL','钢铁',75]])if(!stockDefs.has(id))stockDefs.set(id,{name,limit});
const stockDef=id=>stockDefs.get(id)||{name:itemNames[id]||id,limit:50};
function stockRoom(p,item,k,source){
 const cell=G.stockCells[k],obj=G.fieldObjects[k];if(cell&&cell.item!==item||obj&&obj.kind!=='grass'&&!(k===source&&obj.kind==='pile'&&obj.amount<=stockDef(item).limit-(cell?.amount||0))||G.people.some(other=>other!==p&&other.motion?.stockKey===k))return 0;
 return Math.max(0,stockDef(item).limit-(cell?.amount||0))
}
function storagePath(p,item,source){
 const fill=new Map(),empty=new Map();
 for(const z of G.zones){if(z.type!=='储存区')continue;for(let y=Math.max(0,z.y);y<Math.min(MAP_H,z.y+z.h);y++)for(let x=Math.max(0,z.x);x<Math.min(MAP_W,z.x+z.w);x++){const c={x,y},k=x+','+y;if(!allowed(p,c)||!walkable(c)||!stockRoom(p,item,k,source))continue;
 (G.stockCells[k]?fill:empty).set(y*MAP_W+x,k)}}
 return (fill.size&&paths(p,fill))||(empty.size&&paths(p,empty))||null
}
function takeStock(item,cost){
 if((G.inventory[item]||0)<cost)return false;
 let left=cost;for(const [k,c] of Object.entries(G.stockCells)){if(c.item!==item)continue;const n=Math.min(left,c.amount);c.amount-=n;left-=n;
 let used=n;while(used>0&&c.lots?.length){const lot=c.lots[0],v=Math.min(used,lot.amount);used-=v;lot.amount-=v;if(!lot.amount)c.lots.shift()}
 if(!c.amount)delete G.stockCells[k];if(!left)break}
 G.inventory[item]-=cost;refreshHUD();return true
}
function stockDescription(c){return stockDef(c.item).name+'　'+c.amount+' / '+stockDef(c.item).limit}
function stockDetails(k){const c=G.stockCells[k];if(!c)return;showSheet('储存格 · '+k,[stockDescription(c),'最近入库批次',...(c.lots||[]).slice(-8).reverse().map(l=>l.source+'　×'+l.amount+'　Tick '+l.tick)])}
function stockReport(){const cells=Object.values(G.stockCells),items=new Map();for(const c of cells)items.set(c.item,(items.get(c.item)||0)+c.amount);const slots=new Set();
 for(const z of G.zones.filter(z=>z.type==='储存区'))for(let y=z.y;y<z.y+z.h;y++)for(let x=z.x;x<z.x+z.w;x++){const k=x+','+y,o=G.fieldObjects[k];if(walkable({x,y})&&(!o||o.kind==='grass'||G.stockCells[k]))slots.add(k)}
 const pending=Object.values(G.fieldObjects).filter(o=>o.kind==='pile');showSheet('仓储总览',['已用 '+cells.length+' / '+slots.size+' 个可用格　·　地面待运 '+pending.length+' 堆','同类优先补堆。不同物品使用不同格，满仓时物资保留在地面或搬运者手中。','','物品　｜　区内数量　｜　随营储备　｜　每格上限',...Object.keys(G.inventory).filter(id=>G.inventory[id]>0||items.has(id)).map(id=>stockDef(id).name+'　｜　'+(items.get(id)||0)+'　｜　'+(G.inventory[id]-(items.get(id)||0))+'　｜　'+stockDef(id).limit),'','点击地图上的物资堆，可查看数量和入库来源。'])}
function paintStock(x,y,c){const info=stockDef(c.item),glyph=({'ITM-WOOD':'木','ITM-STONE':'石','ITM-IRON-ORE':'铁','ITM-COPPER-ORE':'铜','ITM-CRYSTAL':'晶','ITM-FOOD':'粮','ITM-MED':'药'})[c.item]||info.name[0];ctx.save();ctx.translate(x*TILE,y*TILE);ctx.fillStyle='#393b31';ctx.fillRect(2,1,20,22);ctx.fillStyle=c.item==='ITM-WOOD'?'#ac815a':c.item==='ITM-MED'?'#829c76':'#9b927a';ctx.fillRect(4,3,16,11);ctx.textAlign='center';ctx.fillStyle='#151d19';ctx.font='bold 10px sans-serif';ctx.fillText(glyph,12,12);ctx.font='bold 9px sans-serif';ctx.fillStyle='#fff3ce';ctx.fillText(String(c.amount),12,21,18);ctx.restore()}


function sendCargo(p){
 const route=storagePath(p,p.cargo.item);if(!route){p.job={name:'携货等待可达的同类余位或空格',target:'储存区',progress:0,reason:'货物仍由本人保管'};return false}
 assign(p,route,'deliver','运送'+(itemNames[p.cargo.item]||p.cargo.item)+'至储存区');p.motion.stockKey=route.found;return true
}
function seekPile(p){
 if(p.priorities?.搬运===0||!G.zones.some(z=>z.type==='储存区')||G.tick<(p.nextHaulScan||0))return false;
 p.nextHaulScan=G.tick+60;
 const goals=new Map(),reserved=new Set(G.people.map(o=>o.motion?.pileKey).filter(Boolean));
 function consider(x,y){const k=x+','+y,o=G.fieldObjects[k];if(o?.kind==='pile'&&!reserved.has(k)&&allowed(p,o)&&walkable(o))goals.set(y*MAP_W+x,o)}
 for(const t of G.orders||[])if(t.cmd==='搬运')consider(t.x,t.y);
 {const {x,y}=p.position;for(let dy=-10;dy<=10;dy++)for(let dx=-10;dx<=10;dx++)if(Math.abs(dx)+Math.abs(dy)<=10)consider(x+dx,y+dy)}
 while(goals.size){const r=paths(p,goals);if(!r)break;const o=r.found,k=o.x+','+o.y,dest=storagePath(p,o.item,k);if(dest){assign(p,r,'pickup','前往拾取'+stockDef(o.item).name);p.motion.pileKey=k;p.motion.stockKey=dest.found;return true}
 for(const [id,c] of goals)if(c.item===o.item&& !G.zones.some(z=>z.type==='储存区'&&inside(c,z))||c===o)goals.delete(id)}return false
}
function finishHaul(p,m){
 if(m.kind==='pickup'){const o=G.fieldObjects[m.pileKey];if(p.priorities?.搬运===0||o?.kind!=='pile'||!storagePath(p,o.item,m.pileKey)){releasePawn(p);return}
 m.work=(m.work||0)+12;p.job.name='拾取物资';p.job.progress=Math.min(100,Math.round(100*m.work/taskTime.搬运));if(m.work<taskTime.搬运)return;
 const dest=storagePath(p,o.item,m.pileKey),amount=Math.min(o.amount,stockRoom(p,o.item,dest.found,m.pileKey));if(!amount){releasePawn(p);return}p.cargo={item:o.item,amount,source:o.source||('地面 '+m.pileKey)};o.amount-=amount;if(!o.amount)delete G.fieldObjects[m.pileKey];if(!o.amount)G.orders=(G.orders||[]).filter(t=>!(t.cmd==='搬运'&&t.x===o.x&&t.y===o.y));releasePawn(p);sendCargo(p);return}
 const dest=G.zones.find(z=>z.type==='储存区'&&inside(p.position,z));if(!p.cargo||!dest||!allowed(p,p.position)){releasePawn(p);return}
 const {item}=p.cargo,k=p.position.x+','+p.position.y,amount=Math.min(p.cargo.amount,stockRoom(p,item,k));if(!amount){releasePawn(p);return}const cell=G.stockCells[k]??={item,amount:0,lots:[]};cell.amount+=amount;cell.lots.push({source:p.cargo.source||'旧档在途物资',amount,tick:G.tick});G.inventory[item]=(G.inventory[item]||0)+amount;
 p.memories.unshift({factId:'HAUL-'+G.tick+'-'+p.id,appraisal:'送达储存区（'+p.position.x+', '+p.position.y+'） · '+(itemNames[item]||item)+' ×'+amount,intensity:1});p.memories.splice(24);
 p.cargo.amount-=amount;if(!p.cargo.amount)delete p.cargo;releasePawn(p);refreshHUD()
}

function dispatch(p){
 const goals=new Map();for(const t of G.orders||[]){if(t.cmd==='搬运'||t.owner||!allowed(p,t))continue;const spots=[[t.x-1,t.y],[t.x+t.w,t.y],[t.x,t.y-1],[t.x,t.y+t.h]];if(t.cmd!=='拆除')spots.push([t.x,t.y]);for(const [x,y] of spots){const c={x,y},key=y*MAP_W+x;if(walkable(c)&&allowed(p,c)&&!goals.has(key))goals.set(key,t)}}
 if(!goals.size)return false;const r=paths(p,goals);if(!r)return false;r.found.owner=p.id;assign(p,r,'order','前往'+r.found.cmd+'地点');return true
}
function stepPawns(){
 if(G.tick<(G.nextPawnStep||0))return;G.nextPawnStep=G.tick+12;const zones=homes();for(const t of G.orders||[])if(t.owner&&!G.people.some(p=>p.id===t.owner&&p.motion?.kind==='order'&&!G.trip?.ids.includes(p.id)))delete t.owner;
 for(const p of G.people||[]){if(G.trip?.ids.includes(p.id)){if(p.motion)releasePawn(p);continue}
 if(!p.motion&&p.job.name.startsWith('满足')&&allowed(p,p.position)){if(!p.cargo&&!dispatch(p))continue}if(!allowed(p,p.position)&&p.motion?.kind!=='return'){releasePawn(p);const ends=new Map();for(const z of zones)for(let y=z.y;y<z.y+z.h;y++)for(let x=z.x;x<z.x+z.w;x++)if(walkable({x,y}))ends.set(y*MAP_W+x,true);const r=paths(p,ends,true);if(r)assign(p,r,'return','返回居住区');else{p.job.name='居住区不可达';continue}}
 if(p.motion?.kind==='pickup'&&p.priorities?.搬运===0)releasePawn(p);if(p.motion?.kind==='order'&&G.orders?.some(t=>t.owner===p.id&&t.cmd==='搬运'))releasePawn(p);if(p.cargo&&(!p.motion||p.motion.kind==='idle')){if(G.tick>=(p.retryDelivery||0)&&!sendCargo(p))p.retryDelivery=G.tick+60;if(p.motion?.kind!=='deliver')continue}if(!p.motion||p.motion.kind==='idle'){if((G.orders||[]).some(t=>!t.owner)&&G.tick>=(p.retryJob||0)){if(!dispatch(p))p.retryJob=G.tick+90}if(!p.motion||p.motion.kind==='idle')seekPile(p)}
 let m=p.motion;if(!m){if(G.tick<(p.idleUntil||0))continue;const candidates=new Map();for(let j=0;j<6;j++){const x=p.position.x+Math.floor(Math.random()*7)-3,y=p.position.y+Math.floor(Math.random()*7)-3;if(walkable({x,y})&&allowed(p,{x,y}))candidates.set(y*MAP_W+x,true)}const r=paths(p,candidates);if(r)assign(p,r,'idle','闲逛');else p.idleUntil=G.tick+90;continue}
 if(m.step){if(G.tick<m.step.start+96)continue;p.position=m.step.to;delete m.step}if(m.path.length){const next=m.path[0];if(!walkable(next)||(m.kind!=='return'&&!allowed(p,next))){releasePawn(p);continue}m.step={start:G.tick,from:{...p.position},to:m.path.shift()};continue}
 if(m.kind==='pickup'||m.kind==='deliver'){finishHaul(p,m);continue}if(m.kind==='order'){const t=(G.orders||[]).find(t=>t.owner===p.id);if(!t){releasePawn(p);continue}t.work+=12;p.job={name:t.cmd+'中',progress:Math.min(100,Math.round(100*t.work/taskTime[t.cmd])),target:t.x+', '+t.y,reason:'已抵达目标，正在作业'};if(t.work>=taskTime[t.cmd])completeOrder(t,p)}
 else{const idle=m.kind==='idle';releasePawn(p);p.idleUntil=G.tick+72+Math.floor(Math.random()*96);if(idle){const {x,y}=p.position,near=[[x,y],[x+1,y],[x-1,y],[x,y+1],[x,y-1]].map(([a,b])=>G.fieldObjects[a+','+b]?.kind);p.job.name=near.includes('tree')?'观察树木':near.some(k=>['stone','iron','copper','crystal'].includes(k))?'端详石块':'驻足休息'}}
 }draw()
}
