function learning(){showSheet('学习助手',['仓储　每格只能放一种物品，优先补满同类堆。底栏「物流」查看储量和上限，点地图堆垛查看来源。建造与远征先消耗区内实物，再使用随营储备。','聚落地块　新局 72 × 72 格，每格约 2 米；初始地表物占 33%。林木、岩块、铁矿、铜矿、晶矿、浆果和药草均可框选。','框选后工作进入队列，空闲队员到场作业。砍伐、采矿、采集产出地面物资堆，划出储存区后，允许搬运的空闲成员会在周围 10 格内寻找掉落物，取货后送达入库。框选搬运可指定更远的物资。在人员工作优先级中将搬运设为 0 可禁用。拆除只影响选区触及的建筑。','矿物库存　'+['ITM-IRON-ORE','ITM-COPPER-ORE','ITM-CRYSTAL','ITM-COAL'].map(k=>itemNames[k]+' '+(G.inventory[k]||0)).join('、'),'区域规划　选择区域后拖动，松开创建，Esc 取消。','人员　点击头像定位；检查器可查看需求、健康、关系和最近记忆。','世界　选择六角地块和队员，准备往返口粮后出发。','工业　从西向东紧邻放置设备。收货仓接收最后一级产物。','','设备及配方',...Object.values(machines).map(([n,i,c,o,v,t])=>n+'　'+(o?(i?i+' ×'+c:'采集')+' → '+o+' ×'+v:'转运或收货')+'　'+(t||'开局可用')),'','工业制度与科技',...[...laws,...studies].map(x=>x[0]+'　'+x[3]),'','研究目录',...DB.techs.map(t=>t.科技名称+'　'+t.玩法解锁),'','建造目录',...allBuildDefs().map(b=>b.名称+'　'+(b.功能定位||b.一级分类))])}
let researchMode='tech',pinnedStudy=null;
function researchTree(){
 const policy=researchMode==='policy',host=$('#techGrid');
 const nodes=policy?DB.policies.map(p=>({id:p.政策ID,name:p.政策名称,pre:p.前置政策ID,tech:p.解锁科技ID,desc:p.机械效果,options:String(p['档位/选项']).split('/'),base:p.默认档位})):DB.techs.map(t=>({id:t.科技ID,name:t.科技名称,pre:t.前置科技ID,desc:t.玩法解锁}));
 const by=new Map(nodes.map(n=>[n.id,n])),depths=new Map(),counts=[],pos=new Map();
 const parents=n=>String(n.pre||'').split(/[;；,，]/).map(k=>k.trim()).filter(k=>by.has(k));
 const done=id=>policy?Object.hasOwn(G.policies,id):G.techDone.includes(id);
 const ready=n=>parents(n).every(done)&&(!policy||!n.tech||n.tech==='开局'||G.techDone.includes(n.tech));
 function depth(n,seen=new Set()){if(depths.has(n))return depths.get(n);if(seen.has(n))return 0;const next=new Set(seen).add(n),v=Math.max(0,...parents(n).map(id=>depth(by.get(id),next)+1));depths.set(n,v);return v}
 for(const n of nodes){const l=depth(n),r=counts[l]||0;counts[l]=r+1;pos.set(n,[l*158+10,r*51+8])}
 let edges='',buttons='';for(const n of nodes){const [x,y]=pos.get(n);for(const id of parents(n)){const [a,b]=pos.get(by.get(id));edges+='<path data-from="'+id+'" data-to="'+n.id+'" d="M'+(a+122)+' '+(b+18)+' C'+(a+143)+' '+(b+18)+' '+(x-18)+' '+(y+18)+' '+x+' '+(y+18)+'"/>'}buttons+='<button class="node '+(done(n.id)?'done':ready(n)?'ready':'')+'" style="width:122px;left:'+x+'px;top:'+y+'px" data-node="'+n.id+'"><svg viewBox="0 0 18 18"><path fill="'+pigments[depth(n)%5]+'" d="m9 0 9 7-4 10H4L0 7z"/><path fill="#fff6" d="M9 0 4 17 0 7z"/></svg>'+n.name+'</button>'}
 host.innerHTML='<div class="treeTabs"><button id="techMode" aria-pressed="'+!policy+'">科技树</button><button id="policyMode" aria-pressed="'+policy+'">政策树</button></div><div class="treeScroll"><div class="treeBoard" style="width:'+counts.length*158+'px;height:'+Math.max(...counts)*51+'px"><svg class="edges">'+edges+'</svg>'+buttons+'</div></div><div id="studyInfo">悬停预览直接前置，点击固定项目。</div><select id="lawOption" aria-label="政策档位" hidden></select><button class="bevel-button" id="confirmTech" disabled>选择项目</button>';
 for(const [sel,mode] of [['#techMode','tech'],['#policyMode','policy']])$(sel).onclick=()=>{researchMode=mode;pinnedStudy=null;researchTree()};
 function detail(id){const n=by.get(id);if(!n)return;const pre=parents(n);for(const b of host.querySelectorAll('[data-node]')){b.classList.toggle('picked',b.dataset.node===id);b.classList.toggle('required',pre.includes(b.dataset.node))}for(const e of host.querySelectorAll('[data-to]'))e.classList.toggle('lit',e.dataset.to===id);
 $('#studyInfo').textContent=n.name+'　｜　'+n.desc+'　｜　直接前置：'+(pre.map(k=>by.get(k).name).join('、')||'无')+(policy&&n.tech?'　｜　科技：'+(DB.techs.find(t=>t.科技ID===n.tech)?.科技名称||n.tech):'');
 const action=$('#confirmTech'),sel=$('#lawOption');sel.hidden=!policy;if(policy){sel.replaceChildren(...n.options.map(v=>new Option(v,v)));sel.value=G.policies[id]||n.base||n.options[0];sel.disabled=!ready(n)}
 action.disabled=!ready(n)||!policy&&done(id);action.textContent=!ready(n)?'前置条件未满足':policy?'实施政策':done(id)?'已完成研究':'完成研究';action.onclick=()=>{if(!ready(n))return;if(policy)G.policies[id]=sel.value;else if(!done(id))G.techDone.push(id);pinnedStudy=id;notify(n.name+(policy?' · '+sel.value:' · 研究完成'));const scroll=host.querySelector('.treeScroll'),xy=[scroll.scrollLeft,scroll.scrollTop];researchTree();host.querySelector('.treeScroll').scrollTo(...xy);renderBuild($('.category-list .active')?.textContent.trim()||'命令')}}
 for(const b of host.querySelectorAll('[data-node]')){b.onmouseenter=b.onfocus=()=>detail(b.dataset.node);b.onclick=()=>{pinnedStudy=b.dataset.node;detail(pinnedStudy)};b.onmouseleave=()=>{if(pinnedStudy)detail(pinnedStudy)}}if(by.has(pinnedStudy))detail(pinnedStudy);const ext=document.createElement('details');ext.innerHTML='<summary>'+ (policy?'工务政策':'工业工艺')+' · 知识 '+state().points+'</summary><div id="industryChoices"></div>';host.append(ext);industrialChoices('#industryChoices',policy?laws:studies,policy?'laws':'studied')
}

